:root{--bg:#f7f2e9;--ink:#1d1a16;--panel:#fffdf8;--accent:#7a2e0e;--accent2:#14532d;--line:#d8cbb8;--focus:#005fcc;--card:#fff}
*{box-sizing:border-box}html,body{height:100%}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink);display:flex;flex-direction:column}
[hidden]{display:none !important}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
:focus-visible{outline:3px solid var(--focus);outline-offset:2px}
button,.btnlike{min-height:48px;min-width:48px;padding:.6rem .9rem;border:1.5px solid var(--ink);border-radius:12px;background:var(--panel);color:var(--ink);font-size:1rem;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:.4rem}
button.primary{background:var(--accent);color:#fff;border-color:var(--accent)}button.danger{background:#fff;color:#8b0000;border-color:#8b0000}button[aria-pressed="true"]{background:var(--accent2);color:#fff}
button:disabled{opacity:.45;cursor:not-allowed}
.topbar{display:flex;justify-content:space-between;gap:1rem;align-items:start;padding:.6rem .9rem;background:var(--panel);border-bottom:2px solid var(--line);flex-wrap:wrap}
h1{font-size:1.35rem;margin:.1rem 0}.sub{margin:.1rem 0;color:#4a4238}main{flex:1;display:flex;flex-direction:column;min-height:0;padding:.6rem}
.toolbar{display:flex;gap:.5rem;flex-wrap:wrap;align-items:center;margin-bottom:.5rem}.toolbar span{min-width:52px;text-align:center;font-weight:700}
#viewport{flex:1;min-height:58vh;border:2px solid var(--ink);border-radius:16px;overflow:hidden;position:relative;background:radial-gradient(circle,#cbbfa8 1px,transparent 1px);background-size:28px 28px;background-color:#efe7d7;touch-action:none;cursor:grab}
#viewport:active{cursor:grabbing}
#world{position:absolute;left:0;top:0;width:4000px;height:3000px;transform-origin:0 0}
#links{position:absolute;inset:0;width:4000px;height:3000px;overflow:visible;pointer-events:none}
#links line{stroke:#7a2e0e;stroke-width:4;stroke-linecap:round;pointer-events:stroke;cursor:pointer}
#links text{font-size:22px}
.pcard{position:absolute;width:240px;background:var(--card);border:2px solid var(--ink);border-radius:14px;box-shadow:0 6px 18px rgba(0,0,0,.18);overflow:hidden;user-select:none;touch-action:none;cursor:grab}
.pcard.selected{outline:4px solid var(--accent2);outline-offset:2px}
.pcard img{width:100%;height:150px;object-fit:cover;display:block;background:#e8dfcf}
.pcard .noimg{height:110px;display:grid;place-items:center;font-size:2.6rem;background:#e8dfcf}
.pcard .body{padding:.55rem .65rem}.badge2{display:inline-block;font-size:.8rem;font-weight:700;border:1.5px solid var(--ink);border-radius:999px;padding:.15rem .5rem;background:#fff8e6}
.pcard p{margin:.4rem 0;font-size:.98rem;line-height:1.35;overflow-wrap:anywhere}
.pcard .actions{display:flex;gap:.4rem;padding:0 .55rem .55rem}.pcard .actions button{min-height:48px;flex:1;font-size:.9rem;padding:.35rem}
.empty{position:absolute;left:60px;top:60px;max-width:420px;background:var(--panel);border:2px dashed var(--ink);border-radius:16px;padding:1.2rem}.empty.small{position:static;margin-top:1rem}
.legend{display:flex;gap:1rem;flex-wrap:wrap;padding:.5rem .2rem;font-weight:600}.muted{color:#4a4238}.small{font-size:.88rem}.hint{background:#fff3cd;border:1.5px solid #7a5a00;border-radius:10px;padding:.5rem .7rem}
.bottombar{display:flex;gap:.6rem;padding:.6rem;background:var(--panel);border-top:2px solid var(--line)}.bottombar button{flex:1}.bottombar button[aria-current="page"]{background:var(--ink);color:#fff}.badge{background:#fff;color:var(--ink);border:1.5px solid var(--ink);border-radius:999px;padding:.05rem .5rem;font-weight:800}
.cardbox,#ordersList article{background:var(--panel);border:1.5px solid var(--line);border-radius:14px;padding:1rem;margin:.7rem 0}
label{font-weight:700;display:block;margin:.7rem 0 .3rem}input,select{width:100%;min-height:48px;font-size:1rem;padding:.6rem;border:1.5px solid var(--ink);border-radius:10px;background:#fff;color:var(--ink)}
.row{display:flex;gap:.6rem;flex-wrap:wrap;align-items:center}.row input{flex:1}.between{justify-content:space-between}
dialog{max-width:min(560px,92vw);width:100%;border:2px solid var(--ink);border-radius:16px;padding:1rem 1.2rem;background:var(--panel);color:var(--ink)}dialog::backdrop{background:rgba(0,0,0,.55)}#preview{width:100%;max-height:220px;object-fit:cover;border-radius:10px;border:1.5px solid var(--ink)}
.toast{position:fixed;left:50%;transform:translateX(-50%);bottom:86px;background:#1d1a16;color:#fff;padding:.7rem 1rem;border-radius:12px;display:flex;gap:.7rem;align-items:center;z-index:20;max-width:92vw}.toast button{min-height:44px}
.top-actions{display:flex;gap:.5rem;flex-wrap:wrap}
@media(max-width:640px){.pcard{width:200px}.topbar{flex-direction:column}#viewport{min-height:62vh}}

const KEY='whole-wall-v1';
const $=s=>document.querySelector(s);
const TYPES={ceramics:'🏺 Ceramics',photography:'📷 Photography',illustration:'✏️ Illustration',idea:'💡 Idea / Other'};
let state=load(); let view={x:40,y:40,k:1}; let editingId=null, pendingImage='', linkMode=false, linkFrom=null, undoSnapshot=null, undoTimer=null, confirmCb=null;
function load(){try{return JSON.parse(localStorage.getItem(KEY))||{cards:[],links:[],orders:[]}}catch{return{cards:[],links:[],orders:[]}}}
function save(){localStorage.setItem(KEY,JSON.stringify(state)); announce('Saved on this device.'); updateCounts();}
function announce(m){$('#status').textContent=m;}
function uid(){return Math.random().toString(36).slice(2,9)+Date.now().toString(36)}
function snapshotUndo(label){undoSnapshot=JSON.stringify(state); $('#undoBtn').disabled=false; showToast(label);}
function showToast(label){clearTimeout(undoTimer); $('#toastText').textContent=label; $('#toast').hidden=false; undoTimer=setTimeout(()=>{$('#toast').hidden=true; undoSnapshot=null; $('#undoBtn').disabled=true;},10000);}
function doUndo(){if(!undoSnapshot)return; state=JSON.parse(undoSnapshot); undoSnapshot=null; $('#toast').hidden=true; $('#undoBtn').disabled=true; save(); render(); renderOrders(); announce('Undone.');}
$('#toastUndo').onclick=doUndo; $('#undoBtn').onclick=doUndo;
// Render
function render(){
  const wrap=$('#cards'); wrap.innerHTML=''; $('#emptyState').style.display=state.cards.length?'none':'block';
  state.cards.forEach(c=>{
    const el=document.createElement('article'); el.className='pcard'+(linkFrom===c.id?' selected':''); el.style.left=c.x+'px'; el.style.top=c.y+'px'; el.dataset.id=c.id;
    el.setAttribute('aria-label',`${TYPES[c.type]}: ${c.note}`);
    el.innerHTML=`${c.img?`<img src="${c.img}" alt="">`:`<div class="noimg" aria-hidden="true">${TYPES[c.type].split(' ')[0]}</div>`}<div class="body"><span class="badge2">${TYPES[c.type]}</span><p></p></div><div class="actions"><button data-act="edit" type="button">✏️ Edit</button><button data-act="link" type="button">🔗 Link</button></div>`;
    el.querySelector('p').textContent=c.note;
    el.querySelector('[data-act="edit"]').onclick=e=>{e.stopPropagation(); openDialog(c.id)};
    el.querySelector('[data-act="link"]').onclick=e=>{e.stopPropagation(); if(!linkMode) setLinkMode(true); pickLink(c.id)};
    el.addEventListener('dblclick',()=>openDialog(c.id));
    el.addEventListener('pointerdown',e=>onCardDown(e,c,el));
    wrap.appendChild(el);
  });
  drawLinks(); applyView();
}
function drawLinks(){
  const svg=$('#links'); svg.innerHTML='';
  state.links.forEach(l=>{const a=state.cards.find(c=>c.id===l.a),b=state.cards.find(c=>c.id===l.b); if(!a||!b)return;
    const line=document.createElementNS('http://www.w3.org/2000/svg','line'); line.setAttribute('x1',a.x+120);line.setAttribute('y1',a.y+90);line.setAttribute('x2',b.x+120);line.setAttribute('y2',b.y+90);
    line.addEventListener('pointerdown',e=>{if(linkMode){e.stopPropagation(); snapshotUndo('Link removed.'); state.links=state.links.filter(x=>x!==l); save(); render();}});
    svg.appendChild(line);
    const t=document.createElementNS('http://www.w3.org/2000/svg','text'); t.setAttribute('x',(a.x+b.x)/2+120); t.setAttribute('y',(a.y+b.y)/2+80); t.textContent='↔ feeds'; svg.appendChild(t);
  });
}
function applyView(){$('#world').style.transform=`translate(${view.x}px,${view.y}px) scale(${view.k})`; $('#zoomLabel').textContent=Math.round(view.k*100)+'%';}
function updateCounts(){$('#orderCount').textContent=state.orders.length;}
// Pan / zoom / drag
const vp=$('#viewport'); const pointers=new Map(); let pan=null, drag=null, pinchDist=0;
vp.addEventListener('pointerdown',e=>{ if(e.target.closest('.pcard'))return; pointers.set(e.pointerId,{x:e.clientX,y:e.clientY}); vp.setPointerCapture(e.pointerId); if(pointers.size===1) pan={x:e.clientX,y:e.clientY,vx:view.x,vy:view.y}; if(pointers.size===2){const p=[...pointers.values()]; pinchDist=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);} });
vp.addEventListener('pointermove',e=>{
  if(drag){const dx=(e.clientX-drag.sx)/view.k, dy=(e.clientY-drag.sy)/view.k; drag.card.x=Math.round(drag.ox+dx); drag.card.y=Math.round(drag.oy+dy); drag.el.style.left=drag.card.x+'px'; drag.el.style.top=drag.card.y+'px'; drawLinks(); return;}
  if(!pointers.has(e.pointerId))return; pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
  if(pointers.size===2){const p=[...pointers.values()]; const d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y); if(pinchDist) zoomAt(view.k*Math.min(1.25,Math.max(.8,d/pinchDist)), (p[0].x+p[1].x)/2,(p[0].y+p[1].y)/2); pinchDist=d; return;}
  if(pan){view.x=pan.vx+(e.clientX-pan.x); view.y=pan.vy+(e.clientY-pan.y); applyView();}
});
function endPointer(e){pointers.delete(e.pointerId); if(pointers.size<2)pinchDist=0; if(pointers.size===0)pan=null; if(drag){drag=null; save();}}
vp.addEventListener('pointerup',endPointer); vp.addEventListener('pointercancel',endPointer);
vp.addEventListener('wheel',e=>{e.preventDefault(); zoomAt(view.k*(e.deltaY<0?1.12:0.89), e.clientX, e.clientY);},{passive:false});
function zoomAt(k,cx,cy){const r=vp.getBoundingClientRect(); const mx=cx-r.left,my=cy-r.top; const wx=(mx-view.x)/view.k, wy=(my-view.y)/view.k; view.k=Math.min(2.5,Math.max(.15,k)); view.x=mx-wx*view.k; view.y=my-wy*view.k; applyView();}
function onCardDown(e,c,el){ if(e.target.closest('button'))return; if(linkMode){pickLink(c.id); return;} drag={card:c,el,sx:e.clientX,sy:e.clientY,ox:c.x,oy:c.y}; el.setPointerCapture(e.pointerId); e.preventDefault(); }
function pickLink(id){ if(!linkFrom){linkFrom=id; announce('First card chosen. Now tap a second card.'); render(); return;} if(linkFrom===id){linkFrom=null; render(); return;}
  if(state.links.some(l=>(l.a===linkFrom&&l.b===id)||(l.b===linkFrom&&l.a===id))){announce('Already linked.'); linkFrom=null; render(); return;}
  snapshotUndo('Link added.'); state.links.push({id:uid(),a:linkFrom,b:id}); linkFrom=null; save(); render(); announce('Cards linked — they could feed each other.'); }
function setLinkMode(on){linkMode=on; linkFrom=null; $('#linkBtn').setAttribute('aria-pressed',String(on)); $('#linkHint').hidden=!on; render();}
$('#linkBtn').onclick=()=>setLinkMode(!linkMode);
$('#zoomInBtn').onclick=()=>zoomAt(view.k*1.2, innerWidth/2, innerHeight/2);
$('#zoomOutBtn').onclick=()=>zoomAt(view.k/1.2, innerWidth/2, innerHeight/2);
$('#fitBtn').onclick=fit; function fit(){ if(!state.cards.length){view={x:40,y:40,k:1};applyView();return;} const minX=Math.min(...state.cards.map(c=>c.x)),minY=Math.min(...state.cards.map(c=>c.y)),maxX=Math.max(...state.cards.map(c=>c.x+240)),maxY=Math.max(...state.cards.map(c=>c.y+260)); const r=vp.getBoundingClientRect(); const k=Math.min(1.5,Math.max(.15,Math.min(r.width/(maxX-minX+80), r.height/(maxY-minY+80)))); view.k=k; view.x=(r.width-(maxX-minX)*k)/2-minX*k; view.y=(r.height-(maxY-minY)*k)/2-minY*k; applyView(); announce('Showing whole wall.'); }
// Dialog add/edit
const dlg=$('#cardDialog');
function openDialog(id=null){ editingId=id; const c=state.cards.find(x=>x.id===id); $('#dialogTitle').textContent=c?'Card focus — edit':'Add a card'; $('#typeInput').value=c?.type||'ceramics'; $('#noteInput').value=c?.note||''; pendingImage=c?.img||''; $('#preview').hidden=!pendingImage; if(pendingImage)$('#preview').src=pendingImage; $('#deleteCardBtn').hidden=!c; $('#imageInput').value=''; updateCount(); dlg.showModal(); $('#noteInput').focus(); }
function updateCount(){$('#charCount').textContent=`${$('#noteInput').value.length} / 140`;}
$('#noteInput').addEventListener('input',updateCount);
$('#addBtn').onclick=()=>openDialog(); $('#emptyAdd').onclick=()=>openDialog();
$('#cancelDialog').onclick=()=>dlg.close();
$('#imageInput').addEventListener('change',async e=>{const f=e.target.files[0]; if(!f)return; pendingImage=await shrink(f); $('#preview').src=pendingImage; $('#preview').hidden=false;});
function shrink(file){return new Promise(res=>{const img=new Image(); const url=URL.createObjectURL(file); img.onload=()=>{const s=Math.min(1,640/img.width); const cv=document.createElement('canvas'); cv.width=Math.round(img.width*s); cv.height=Math.round(img.height*(s||1)); cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height); URL.revokeObjectURL(url); res(cv.toDataURL('image/jpeg',.72));}; img.src=url;});}
$('#cardForm').addEventListener('submit',e=>{e.preventDefault(); const note=$('#noteInput').value.trim(); if(!note){announce('A one-line note is required.'); return;}
  if(editingId){const c=state.cards.find(x=>x.id===editingId); Object.assign(c,{note,type:$('#typeInput').value,img:pendingImage}); announce('Card updated.');}
  else{const r=vp.getBoundingClientRect(); const wx=(r.width/2-view.x)/view.k-120, wy=(r.height/2-view.y)/view.k-100; state.cards.push({id:uid(),note,type:$('#typeInput').value,img:pendingImage,x:Math.round(wx+Math.random()*60),y:Math.round(wy+Math.random()*40)}); announce('Card pinned to wall. Drag it anywhere.');}
  save(); render(); dlg.close();});
$('#deleteCardBtn').onclick=()=>{confirmAction('Delete this card and its links?',()=>{snapshotUndo('Card deleted.'); state.cards=state.cards.filter(c=>c.id!==editingId); state.links=state.links.filter(l=>l.a!==editingId&&l.b!==editingId); save(); render(); dlg.close();});};
// Confirm
function confirmAction(text,cb){$('#confirmText').textContent=text; confirmCb=cb; $('#confirmDialog').showModal();}
$('#confirmNo').onclick=()=>$('#confirmDialog').close(); $('#confirmYes').onclick=()=>{$('#confirmDialog').close(); confirmCb&&confirmCb();};
// Orders
function show(screen){ const wall=screen==='wall'; $('#wallScreen').hidden=!wall; $('#ordersScreen').hidden=wall; $('#navWall').setAttribute('aria-current',wall?'page':'false'); $('#navOrders').setAttribute('aria-current',!wall?'page':'false'); if(!wall)renderOrders(); }
$('#navWall').onclick=()=>show('wall'); $('#navOrders').onclick=()=>show('orders');
$('#saveOrderBtn').onclick=()=>{show('orders'); $('#orderName').focus();};
$('#saveForm').addEventListener('submit',e=>{e.preventDefault(); const name=$('#orderName').value.trim(); if(!name)return; snapshotUndo('Story order saved.'); state.orders.unshift({id:uid(),name,at:new Date().toLocaleString(),cards:JSON.parse(JSON.stringify(state.cards.map(c=>({id:c.id,x:c.x,y:c.y})))),links:JSON.parse(JSON.stringify(state.links))}); $('#orderName').value=''; save(); renderOrders();});
function renderOrders(){ const list=$('#ordersList'); list.innerHTML=''; $('#noOrders').style.display=state.orders.length?'none':'block'; updateCounts();
  state.orders.forEach(o=>{const a=document.createElement('article'); a.innerHTML=`<h3></h3><p class="muted small">${o.at} · ${o.cards.length} cards · ${o.links.length} links</p><div class="row"><button data-a="restore">Restore exactly</button><button data-a="dup">Duplicate</button><button data-a="del" class="danger">Delete</button></div>`; a.querySelector('h3').textContent=o.name;
    a.querySelector('[data-a="restore"]').onclick=()=>{snapshotUndo('Order restored: '+o.name); o.cards.forEach(p=>{const c=state.cards.find(x=>x.id===p.id); if(c){c.x=p.x;c.y=p.y;}}); state.links=JSON.parse(JSON.stringify(o.links)).filter(l=>state.cards.some(c=>c.id===l.a)&&state.cards.some(c=>c.id===l.b)); save(); render(); show('wall'); fit();};
    a.querySelector('[data-a="dup"]').onclick=()=>{snapshotUndo('Order duplicated.'); state.orders.unshift({...JSON.parse(JSON.stringify(o)),id:uid(),name:o.name+' (copy)',at:new Date().toLocaleString()}); save(); renderOrders();};
    a.querySelector('[data-a="del"]').onclick=()=>confirmAction(`Delete story order “${o.name}”?`,()=>{snapshotUndo('Story order deleted.'); state.orders=state.orders.filter(x=>x.id!==o.id); save(); renderOrders();});
    list.appendChild(a);});}
// Export / import / delete all
$('#exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='whole-wall-export.json'; a.click(); URL.revokeObjectURL(a.href); announce('Export downloaded.');};
$('#importFile').addEventListener('change',async e=>{const f=e.target.files[0]; if(!f)return; try{const d=JSON.parse(await f.text()); if(!Array.isArray(d.cards))throw 0; snapshotUndo('Import complete.'); state={cards:d.cards,links:d.links||[],orders:d.orders||[]}; save(); render(); renderOrders();}catch{announce('That file could not be imported.');}});
$('#deleteAllBtn').onclick=()=>confirmAction('Delete ALL cards, links and saved orders on this device? Export first if you want a copy.',()=>{snapshotUndo('All data deleted.'); state={cards:[],links:[],orders:[]}; save(); render(); renderOrders(); show('wall');});
// Keyboard nudge for focused card container via viewport arrows when a card selected? Keep simple: fit on F
vp.addEventListener('keydown',e=>{const step=20/view.k; if(e.key==='ArrowLeft'){view.x+=step*view.k;applyView();} if(e.key==='ArrowRight'){view.x-=step*view.k;applyView();} if(e.key==='ArrowUp'){view.y+=step*view.k;applyView();} if(e.key==='ArrowDown'){view.y-=step*view.k;applyView();} if(e.key==='+'||e.key==='=')zoomAt(view.k*1.15,innerWidth/2,innerHeight/2); if(e.key==='-')zoomAt(view.k/1.15,innerWidth/2,innerHeight/2);});
render(); renderOrders(); if(state.cards.length) fit();

:root{--bg:#f7f5ef;--card:#fff;--ink:#1d2a22;--muted:#4d5a51;--accent:#1f6f4a;--accent2:#14532d;--danger:#9b2226;--line:#cbd5cc;--focus:#ffbf47;--radius:18px}
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink);line-height:1.55}
[hidden]{display:none!important}
.topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem;padding:1rem;max-width:640px;margin:0 auto}
h1{font-size:1.45rem;line-height:1.2;margin:.2rem 0}.subtitle{margin:.2rem 0;color:var(--muted)}
main{max-width:640px;margin:0 auto;padding:0 1rem 2rem;display:flex;flex-direction:column;gap:1rem}
section,.more-panel,.done-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:1.1rem}
.step-indicator{font-weight:700;margin:.2rem 0 0}.step-track{height:10px;background:#e2e8e2;border-radius:99px;overflow:hidden}.step-track span{display:block;height:100%;background:var(--accent);width:33%;transition:width .3s}
.status{min-height:1.5em;font-weight:600}.status:empty{display:none}.date-line{color:var(--muted);margin:0}.hint{background:#eef6f0;border-left:5px solid var(--accent);padding:.7rem .9rem;border-radius:10px}
.big-btn{display:flex;align-items:center;justify-content:center;gap:.6rem;width:100%;min-height:76px;font-size:1.25rem;font-weight:800;border:0;border-radius:999px;background:var(--accent);color:#fff;cursor:pointer;padding:1rem;margin:.8rem 0;touch-action:manipulation}
.big-btn:hover{background:var(--accent2)}.record-btn.recording{background:var(--danger)}.done-btn{background:var(--accent2)}
.dot{width:16px;height:16px;border-radius:50%;background:#fff;flex:none}.recording .dot{animation:pulse 1s infinite}@keyframes pulse{50%{opacity:.3}}
.secondary-btn,.ghost-btn,.danger-btn{min-height:52px;font-size:1rem;font-weight:700;border-radius:999px;padding:.7rem 1.1rem;cursor:pointer;touch-action:manipulation}
.secondary-btn{background:#fff;color:var(--accent2);border:2px solid var(--accent)}.ghost-btn{background:transparent;color:var(--accent2);border:2px solid transparent;text-decoration:underline}.danger-btn{background:#fff;color:var(--danger);border:2px solid var(--danger)}.wide{width:100%;margin:.4rem 0}
.transcript-box{background:#fbfbf7;border:1px solid var(--line);border-radius:12px;padding:.9rem;min-height:64px;font-size:1.1rem}.captions span{padding:.05rem .15rem;border-radius:4px}.captions span.active{background:#ffe58a;color:#111;font-weight:700}
.field{display:flex;flex-direction:column;gap:.4rem;font-weight:600;margin:.8rem 0}input,textarea{font:inherit;padding:.8rem;border:2px solid #8a9a8d;border-radius:12px;background:#fff;color:var(--ink);width:100%}
.label{font-weight:700;margin:.9rem 0 .3rem}.muted{color:var(--muted)}.small{font-size:.9rem}
.level-track{height:16px;background:#e2e8e2;border-radius:99px;overflow:hidden}.level-track span{display:block;height:100%;width:0;background:var(--accent)}
.timer{font-size:1.6rem;font-weight:800;margin:.4rem 0}.timer .muted{font-size:1rem}
.chips{display:flex;flex-wrap:wrap;gap:.5rem}.chip{min-height:52px;padding:.6rem 1rem;border-radius:999px;border:2px solid var(--accent);background:#fff;color:var(--accent2);font-weight:700;font-size:1rem;cursor:pointer}.chip[aria-pressed="true"]{background:var(--accent);color:#fff}
.nav-row{display:flex;justify-content:space-between;align-items:center;gap:.8rem;margin-top:1rem;flex-wrap:wrap}.nav-primary{width:auto;flex:1;margin:0;min-height:60px;font-size:1.05rem}
.instruction-card{border:2px solid var(--accent);border-radius:var(--radius);padding:1rem;background:#eef6f0}.card-kicker{font-weight:700;margin:.2rem 0}.step-text{font-size:1.45rem;font-weight:800;line-height:1.35;margin:.4rem 0}
.done-card{text-align:center;padding:2rem 1rem}.done-icon{font-size:3rem;margin:0}.more-wrap{text-align:center}.more-panel{text-align:left;margin-top:.6rem}
.footer{max-width:640px;margin:0 auto;padding:0 1rem 1.5rem}
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:4px solid var(--focus);outline-offset:3px}
body.focus-mode .topbar .subtitle,body.focus-mode .more-wrap,body.focus-mode .footer,body.focus-mode .date-line,body.focus-mode .hint{display:none}
body.focus-mode main{padding-top:1rem}
@media(min-width:700px){h1{font-size:1.8rem}section{padding:1.4rem}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

const $=s=>document.querySelector(s);
const statusEl=$('#status');
const todayKey=()=>{const d=new Date();return d.toISOString().slice(0,10)};
const announce=m=>{statusEl.textContent=m};
$('#dateLine').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});

// IndexedDB — one store, keyed by date. Only today's row is ever read/shown.
const dbP=new Promise((res,rej)=>{const r=indexedDB.open('one-thing-walk',1);r.onupgradeneeded=()=>r.result.createObjectStore('days',{keyPath:'date'});r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
async function idb(op,arg){const db=await dbP;return new Promise((res,rej)=>{const tx=db.transaction('days','readwrite');const st=tx.objectStore('days');let rq;if(op==='put')rq=st.put(arg);if(op==='get')rq=st.get(arg);if(op==='delete')rq=st.delete(arg);if(op==='clear')rq=st.clear();rq.onsuccess=()=>res(rq.result);rq.onerror=()=>rej(rq.error)})}

const SCREENS=['screenRecord','screenReview','screenStep','screenDone'];
let stepNum=1;
function show(id){
  SCREENS.forEach(s=>{$('#'+s).hidden=s!==id});
  stepNum=id==='screenRecord'?1:id==='screenReview'?2:3;
  const names={1:'Capture',2:'Listen & check',3:'One step'};
  const ind=$('#stepIndicator');
  if(id==='screenDone'){ind.textContent='Done \u2014 finished for today';$('#stepBar').style.width='100%'}
  else{ind.textContent=`Step ${stepNum} of 3 \u2014 ${names[stepNum]}`;$('#stepBar').style.width=(stepNum/3*100)+'%'}
  const h=$('#'+id+' h2'); if(h){h.setAttribute('tabindex','-1');h.focus?.({preventScroll:false})}
  window.scrollTo({top:0,behavior:'smooth'});
}

// State
let audioBlob=null,audioUrl=null,mediaRec=null,chunks=[],stream=null,recStart=0,timerId=null,levelCtx=null,levelRaf=null;
let selectedType='melody',stepIndex=0,currentStep='',doneFlag=false;
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
if(!SR)$('#speechFallback').hidden=false;

// Chips
$('#typeChips').addEventListener('click',e=>{const b=e.target.closest('.chip');if(!b)return;selectedType=b.dataset.type;document.querySelectorAll('.chip').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));announce('Type: '+b.textContent.trim())});
function guessType(t){t=t.toLowerCase();if(/hum|melody|chorus|tune|sing|la la/.test(t))return'melody';if(/story|scene|character|episode|once upon/.test(t))return'story';if(/line|rhyme|word|lyric|wrote|write/.test(t))return'line';return'idea'}
function setType(t){selectedType=t;document.querySelectorAll('.chip').forEach(c=>c.setAttribute('aria-pressed',String(c.dataset.type===t)))}

// Step generator — one concrete physical action, <15 min
const STEPS={
 melody:['Hum the chorus twice through, then re-record it once, slower.','Clap the rhythm of the tune four times, then hum it once at that steady speed.','Sing the strongest 10 seconds three times, standing up, phone at arm\u2019s length.'],
 line:['Say the line out loud five times, each time a little slower. Pick the version that lands.','Write the line once on paper, underline the best word, and say it again twice.','Record the line three ways: whisper, normal voice, and like you mean it. Keep the last one.'],
 story:['Act out the opening scene aloud for two minutes, standing up. Stop at the first surprise.','Say what happens next in one sentence, then record just that sentence twice.','Tell the scene to an imaginary friend, out loud, in under three minutes. No restarting.'],
 idea:['Say the idea out loud in one sentence, then record that sentence twice, slower the second time.','Make the smallest physical version now: hum it, sketch it, or act it for 60 seconds.','Name one object in the room this idea is about, pick it up, and talk about the idea for two minutes while holding it.']};
function makeStep(){const pool=STEPS[selectedType]||STEPS.idea;currentStep=pool[stepIndex%pool.length];$('#stepText').textContent=currentStep;$('#stepEcho').textContent=shortEcho()}
function shortEcho(){const t=$('#transcriptEdit').value.trim();return t?t.slice(0,80)+(t.length>80?'\u2026':''):'your memo today'}

// Speech recognition for live transcript
let recog=null,finalText='';
function startRecog(target){
  if(!SR)return null;
  try{const r=new SR();r.continuous=true;r.interimResults=true;r.lang='en';
  r.onresult=e=>{let interim='';for(const res of e.results){if(res.isFinal)finalText+=res[0].transcript+' ';else interim+=res[0].transcript}
    const txt=(finalText+interim).trim();
    if(target==='live'){$('#liveTranscript').textContent=txt||'Listening\u2026'}$('#transcriptEdit').value=txt;};
  r.onerror=()=>{};r.start();return r}catch{return null}
}

// Recording
async function startRecording(){
  try{stream=await navigator.mediaDevices.getUserMedia({audio:true})}catch{announce('Microphone blocked. Allow microphone access, or use a memo file in More options.');return}
  chunks=[];finalText='';$('#transcriptEdit').value='';$('#liveTranscript').textContent='Listening\u2026';
  mediaRec=new MediaRecorder(stream);mediaRec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
  mediaRec.onstop=stopRecordingCleanup;mediaRec.start(250);
  recog=startRecog('live');
  recStart=Date.now();$('#recordingUI').hidden=false;
  const btn=$('#recordBtn');btn.classList.add('recording');btn.setAttribute('aria-pressed','true');$('#recordBtnLabel').innerHTML='&#11035; Stop recording';
  announce('Recording. Tap the big button again to stop. Up to 5 minutes.');
  timerId=setInterval(()=>{const s=Math.floor((Date.now()-recStart)/1000);$('#timer').textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0');if(s>=300)stopRecording()},500);
  // live level
  try{levelCtx=new(window.AudioContext||window.webkitAudioContext)();const src=levelCtx.createMediaStreamSource(stream);const an=levelCtx.createAnalyser();an.fftSize=256;src.connect(an);const data=new Uint8Array(an.frequencyBinCount);const tick=()=>{an.getByteFrequencyData(data);const avg=data.reduce((a,b)=>a+b,0)/data.length;const pct=Math.min(100,Math.round(avg*1.8));$('#levelBar').style.width=pct+'%';$('#levelMeter').setAttribute('aria-valuenow',pct);levelRaf=requestAnimationFrame(tick)};tick()}catch{}
}
function stopRecording(){if(mediaRec&&mediaRec.state!=='inactive')mediaRec.stop()}
function stopRecordingCleanup(){
  clearInterval(timerId);cancelAnimationFrame(levelRaf);levelCtx?.close().catch(()=>{});stream?.getTracks().forEach(t=>t.stop());recog?.stop();
  const btn=$('#recordBtn');btn.classList.remove('recording');btn.setAttribute('aria-pressed','false');$('#recordBtnLabel').innerHTML='\uD83C\uDFA4 Record today\u2019s memo';$('#recordingUI').hidden=true;
  audioBlob=new Blob(chunks,{type:mediaRec?.mimeType||'audio/webm'});setAudio(audioBlob);
  const typed=$('#typedFallback').value.trim();if(typed&&!$('#transcriptEdit').value.trim())$('#transcriptEdit').value=typed;
  const txt=$('#transcriptEdit').value.trim();if(txt)setType(guessType(txt));renderCaptions();
  announce(audioBlob.size?'Recorded. Listen back and check the words.':'Recording stopped.');
  if(audioBlob.size)show('screenReview');
}
function setAudio(blob){if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(blob);$('#audio').src=audioUrl}
$('#recordBtn').addEventListener('click',()=>{mediaRec&&mediaRec.state==='recording'?stopRecording():startRecording()});

// Typed fallback path (skip recording entirely)
$('#typedFallback').addEventListener('input',e=>{$('#useTypedBtn').hidden=!e.target.value.trim()});
$('#useTypedBtn').addEventListener('click',()=>{$('#transcriptEdit').value=$('#typedFallback').value.trim();setType(guessType($('#transcriptEdit').value));audioBlob=null;renderCaptions();announce('Phrase added. Check it, then confirm.');show('screenReview')});

// File import (More)
$('#fileInput').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;audioBlob=f;setAudio(f);renderCaptions();announce('Memo file loaded. Listen back, then confirm.');$('#morePanel').hidden=true;$('#moreBtn').setAttribute('aria-expanded','false');show('screenReview')});

// Playback + synced caption highlighting
const audio=$('#audio');let playing=false;
function togglePlay(){if(!audio.src){announce('Nothing to play yet. Record first.');return}if(audio.paused){audio.play();playing=true;$('#playBtn').innerHTML='&#10073;&#10073; Pause';$('#playBtn').setAttribute('aria-pressed','true')}else{audio.pause()}}
$('#playBtn').addEventListener('click',togglePlay);
$('#listenAgainBtn').addEventListener('click',()=>{if(audio.src){audio.currentTime=0;audio.play();announce('Playing today\u2019s memo.')}});
audio.addEventListener('ended',()=>{playing=false;$('#playBtn').innerHTML='&#9654;\uFE0F Play today\u2019s memo';$('#playBtn').setAttribute('aria-pressed','false');highlightWord(-1)});
audio.addEventListener('pause',()=>{$('#playBtn').innerHTML='&#9654;\uFE0F Play today\u2019s memo';$('#playBtn').setAttribute('aria-pressed','false')});
function renderCaptions(){const t=$('#transcriptEdit').value.trim();const box=$('#captionBox');box.innerHTML='';if(!t){box.textContent='No words yet \u2014 they appear here automatically when speech is recognised, or after you add a short phrase.';return}t.split(/\s+/).forEach(w=>{const s=document.createElement('span');s.textContent=w;box.appendChild(s);box.appendChild(document.createTextNode(' '))})}
function highlightWord(idx){[...$('#captionBox').children].forEach((s,i)=>s.classList.toggle('active',i===idx))}
audio.addEventListener('timeupdate',()=>{if(!audio.duration)return;const words=$('#captionBox').children.length;if(!words)return;highlightWord(Math.min(words-1,Math.floor(audio.currentTime/audio.duration*words)))});
$('#transcriptEdit').addEventListener('input',renderCaptions);

// Navigation
$('#backFromReview').addEventListener('click',()=>show('screenRecord'));
$('#backFromStep').addEventListener('click',()=>show('screenReview'));
$('#confirmBtn').addEventListener('click',async()=>{
  renderCaptions();makeStep();
  await save();announce('Saved on this device. Here is your one step.');show('screenStep');
});
$('#anotherStepBtn').addEventListener('click',async()=>{stepIndex++;makeStep();await save();announce('New single step shown. Still just one thing.')});

async function save(){await idb('put',{date:todayKey(),transcript:$('#transcriptEdit').value.trim(),type:selectedType,step:currentStep,stepIndex,done:doneFlag,audioBlob:audioBlob||null,mime:audioBlob?.type||'',savedAt:Date.now()})}

// Done — tap or voice
async function markDone(){
  doneFlag=true;await save();
  $('#doneStepEcho').textContent='You did: '+currentStep;
  voiceRecog?.stop();$('#voiceDoneHint').hidden=true;$('#sayDoneBtn').setAttribute('aria-pressed','false');
  announce('Done for today. Nice work. You can stop now.');show('screenDone');
}
$('#doneBtn').addEventListener('click',markDone);
let voiceRecog=null;
$('#sayDoneBtn').addEventListener('click',()=>{
  if(voiceRecog){voiceRecog.stop();voiceRecog=null;$('#voiceDoneHint').hidden=true;$('#sayDoneBtn').setAttribute('aria-pressed','false');return}
  if(!SR){announce('Voice commands aren\u2019t supported here \u2014 the big Done button works the same.');return}
  try{voiceRecog=new SR();voiceRecog.continuous=true;voiceRecog.interimResults=true;voiceRecog.lang='en';
  voiceRecog.onresult=e=>{const said=[...e.results].map(r=>r[0].transcript).join(' ').toLowerCase();if(/\bdone\b|finished|that'?s it/.test(said))markDone()};
  voiceRecog.onend=()=>{voiceRecog=null;$('#voiceDoneHint').hidden=true;$('#sayDoneBtn').setAttribute('aria-pressed','false')};
  voiceRecog.onerror=()=>{announce('Could not hear that. Tap Done instead.')};
  voiceRecog.start();$('#voiceDoneHint').hidden=false;$('#sayDoneBtn').setAttribute('aria-pressed','true');announce('Listening. Say done.')}catch{announce('Voice not available. Tap Done.')}
});

// More panel, focus, export, delete
$('#moreBtn').addEventListener('click',()=>{const p=$('#morePanel');p.hidden=!p.hidden;$('#moreBtn').setAttribute('aria-expanded',String(!p.hidden))});
$('#focusBtn').addEventListener('click',()=>{const on=document.body.classList.toggle('focus-mode');$('#focusBtn').setAttribute('aria-pressed',String(on));announce(on?'Focus mode on. Only the current step is shown.':'Focus mode off.')});
$('#exportBtn').addEventListener('click',async()=>{
  const rec=await idb('get',todayKey());
  const data={tool:'One Thing From Today\u2019s Walk',date:todayKey(),transcript:rec?.transcript||$('#transcriptEdit').value.trim(),type:rec?.type||selectedType,nextStep:rec?.step||currentStep,done:!!rec?.done,hasAudio:!!rec?.audioBlob,audioType:rec?.mime||'',exportedAt:new Date().toISOString()};
  const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));
  const a=document.createElement('a');a.href=url;a.download='one-thing-'+todayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);announce('Exported today as JSON.');
});
$('#deleteTodayBtn').addEventListener('click',async()=>{
  await idb('delete',todayKey());audioBlob=null;audio.pause();audio.removeAttribute('src');$('#transcriptEdit').value='';$('#typedFallback').value='';doneFlag=false;stepIndex=0;renderCaptions();announce('Today\u2019s memo and words deleted from this device.');show('screenRecord');
});
$('#deleteAllBtn').addEventListener('click',async()=>{
  await idb('clear');localStorage.clear();audioBlob=null;audio.pause();audio.removeAttribute('src');$('#transcriptEdit').value='';$('#typedFallback').value='';doneFlag=false;renderCaptions();announce('All on-device data deleted.');show('screenRecord');
});

// Restore ONLY today (past days stay hidden — fresh start each morning)
(async()=>{try{const rec=await idb('get',todayKey());if(!rec||(!rec.transcript&&!rec.audioBlob))return;
  if(rec.audioBlob){audioBlob=rec.audioBlob;setAudio(audioBlob)}
  $('#transcriptEdit').value=rec.transcript||'';setType(rec.type||guessType(rec.transcript||''));stepIndex=rec.stepIndex||0;currentStep=rec.step||'';doneFlag=!!rec.done;renderCaptions();
  if(currentStep)$('#stepText').textContent=currentStep;
  if(doneFlag){$('#doneStepEcho').textContent='You did: '+currentStep;show('screenDone')}
  else if(rec.transcript||rec.audioBlob){makeStep();if(rec.step){currentStep=rec.step;$('#stepText').textContent=currentStep}show('screenStep')}
  announce('Welcome back. Today\u2019s one thing is ready.');
}catch{}})();
renderCaptions();
